const input = $input.first().json || {};
const sessionId = String(input.session_id || '')
  .trim()
  .replace(/^whatsapp:/i, '')
  .replace(/\s+/g, '');

if (!/^\+[1-9]\d{7,14}$/.test(sessionId)) {
  throw new Error('SANDBOX_AUTHORIZED_WHATSAPP_SESSION_REQUIRED');
}

return [{ json: { ...input, session_id: sessionId } }];

const event = $input.first().json || {};
const session = event?.data?.object || {};
const metadata = session.metadata || {};
const normalizeId = (value) => {
  if (value && typeof value === 'object') return value.id || '';
  return value == null ? '' : String(value);
};
const whatsappId = String(metadata.whatsapp_id ?? '')
  .trim()
  .replace(/^whatsapp:/i, '')
  .replace(/\s+/g, '')
  .trim();
const completedAt = Number.isFinite(Number(event.created))
  ? new Date(Number(event.created) * 1000).toISOString()
  : '';

return [{
  json: {
    event_id: normalizeId(event.id),
    checkout_session_id: normalizeId(session.id),
    mode: String(session.mode ?? '').toLowerCase(),
    payment_status: String(session.payment_status ?? '').toLowerCase(),
    payment_intent_id: normalizeId(session.payment_intent),
    customer_id: normalizeId(session.customer),
    email: String(session.customer_details?.email ?? '').trim().toLowerCase(),
    amount_total: Number.isFinite(Number(session.amount_total)) ? Number(session.amount_total) : null,
    currency: String(session.currency ?? '').toLowerCase(),
    whatsapp_id: whatsappId,
    user_id: String(metadata.user_id ?? '').trim(),
    acquisition_source: String(metadata.acquisition_source ?? 'whatsapp').trim().toLowerCase(),
    purchase_type: String(metadata.purchase_type ?? ''),
    program_version: String(metadata.program_version ?? ''),
    purchased_at: completedAt,
    raw_event: event
  }
}];

const data = $input.first().json;
const errors = [];
if (data.mode !== 'payment') errors.push('mode must be payment');
if (data.payment_status !== 'paid') errors.push('payment_status must be paid');
if (data.purchase_type !== '28_day_program') errors.push('purchase_type must be 28_day_program');
if (data.program_version !== '1') errors.push('program_version must be 1');
if (data.currency !== 'mxn') errors.push('currency must be mxn');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email || '') || data.email.length > 254) errors.push('Stripe customer email is required');
if (data.amount_total !== 14900) errors.push('amount_total must be 14900');
if (data.acquisition_source === 'website') {
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(data.user_id || '')) {
    errors.push('canonical website user_id is required');
  }
  if (data.whatsapp_id) errors.push('website Checkout must not include whatsapp_id');
} else {
  if (data.acquisition_source !== 'whatsapp') errors.push('unsupported acquisition source');
  if (!data.whatsapp_id) errors.push('normalized whatsapp_id is required');
}
if (!data.checkout_session_id) errors.push('checkout_session_id is required');
if (!data.payment_intent_id) errors.push('payment_intent_id is required');
if (!data.purchased_at) errors.push('Stripe event completion time is required');

return [{ json: { ...data, validation_valid: errors.length === 0, validation_errors: errors } }];

const normalized = $('Sandbox Normalize Stripe Checkout Event').item.json;
const response = $input.first().json || {};
const lineItems = Array.isArray(response.data) ? response.data : [];
const expectedPriceId = 'price_1U1SvtCXkbpCbNJI0sAqDeQF';
const item = lineItems.length === 1 ? lineItems[0] : null;
const price = item?.price || {};
const priceId = typeof price === 'string' ? price : price.id;
const product = typeof price === 'object' ? price.product : null;
const productId = typeof product === 'string' ? product : (product?.id || null);
const errors = [];

if (lineItems.length !== 1) errors.push('Checkout Session must contain exactly one line item');
if (priceId !== expectedPriceId) errors.push('Stripe Price ID does not match the 28-day program Price');
if (Number(item?.quantity) !== 1) errors.push('Checkout Session line-item quantity must be 1');

return [{
  json: {
    ...normalized,
    verified_price_id: priceId || '',
    verified_product_id: productId || '',
    price_validation_valid: errors.length === 0,
    validation_errors: errors
  }
}];

